"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5755],{23933:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"","params":[{"name":"clock","desc":"Defaults to `os.time`. Pass a closure over a local for full control.","lua_type":"Clock?"}],"returns":[{"desc":"","lua_type":"InMemoryStore\\n"}],"function_type":"static","source":{"line":61,"path":"src/stores/InMemory.luau"}},{"name":"failNext","desc":"Makes the next `count` calls to `operation` fail, as a store outage would.\\nOperation names are the method names: `get`, `set`, `update`, `remove`,\\n`sortedSet`, `sortedRemove`, `sortedRange`.","params":[{"name":"self","desc":"","lua_type":"InMemoryStore"},{"name":"operation","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":79,"path":"src/stores/InMemory.luau"}},{"name":"conflictNext","desc":"Makes the next `count` updates lose a compare-and-set race: the transform\\nruns once against the value it read, that result is thrown away, `mutator`\\ninstalls a competing write, and the transform runs again against the new\\nvalue \u2014 which is what MemoryStore\'s `UpdateAsync` does under contention.\\n\\nThis is the only way to catch a transform that forgets to reset its own\\nbookkeeping on re-entry, which every conditional write in Muster depends on.","params":[{"name":"self","desc":"","lua_type":"InMemoryStore"},{"name":"operation","desc":"","lua_type":"string"},{"name":"count","desc":"","lua_type":"number?"},{"name":"mutator","desc":"Receives the current value, returns the competing writer\'s value. Omit to re-run against unchanged state.","lua_type":"((any) -> any)?"}],"returns":[],"function_type":"static","source":{"line":95,"path":"src/stores/InMemory.luau"}},{"name":"callCount","desc":"Total calls made, by operation. Muster\'s suite asserts against this to keep\\nthe request budget from regressing.","params":[{"name":"self","desc":"","lua_type":"InMemoryStore"},{"name":"operation","desc":"","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":284,"path":"src/stores/InMemory.luau"}}],"properties":[],"types":[],"name":"InMemoryStore","desc":"A complete [Store] in a table, with a synthetic clock, working TTL expiry,\\ncall counting, and fault injection. Muster\'s own suite runs entirely against\\nit, and it ships publicly so your tests can too \u2014 no MemoryStore, no Studio,\\nno waiting.\\n\\n```lua\\nlocal now = 0\\nlocal store = Muster.stores.InMemory.new(function() return now end)\\n\\nlocal queue = Muster.new({\\n\\tname = \\"test\\", size = 2,\\n\\tstore = store, clock = function() return now end,\\n\\tautoStart = false, broadcast = false,\\n})\\n\\nqueue:enqueue(1)\\nqueue:enqueue(2)\\nqueue:step()          -- matched, deterministically, with no yielding\\n\\nnow += 200            -- everything expires exactly like it would live\\n```\\n\\nTwo hooks exist purely for tests: [InMemoryStore:failNext] makes the next\\ncalls fail, and [InMemoryStore:conflictNext] makes an update lose a\\ncompare-and-set race.","source":{"line":32,"path":"src/stores/InMemory.luau"}}')}}]);